impl<'a> ListNode<'a> for Plus0<'a> {
    fn iter(&'a self) -> IntoIter<ParseTree<'a>> {
        let mut items = vec![];
        let mut current = self;
        loop {
            match current {
                Plus0::Alt0 {
                    import_declarations_0: rest,
                    layout,
                    import_declaration_2: item,
                    ..
                } => {
                    items.push(item.as_parse_tree());
                    items.push(layout.as_parse_tree());
                    current = rest;
                }
                Plus0::Alt1 {
                    import_declaration: item,
                    ..
                } => {
                    items.push(item.as_parse_tree());
                    break;
                }
                Plus0::Amb(_) => {
                    items.push(ParseTree::Plus0(current));
                    break;
                }
            }
        }
        items.reverse();
        items.into_iter()
    }
}
